def por_ficha3():
    d = {}
    for fid, sp, f, a, l in P3:
        u, pg = url(f)
        d.setdefault(fid, []).append({'sp': sp, 'url': u, 'autor': a, 'licencia': l, 'licenciaUrl': fotos.LU[l], 'pagina': pg, 'origen': 'Wikimedia Commons'})
    return d
